<?php $role=$_SESSION['user']['role']; ?>
<?php if(in_array($role,['admin','teacher'],true)): ?><p><a class="button" href="/students/create">Create student</a></p><?php endif ?>
<form class="filters" method="get" action="/students">
<div><label for="name">Search name</label><input id="name" name="name" maxlength="100" value="<?= e(is_string($_GET['name']??null)?$_GET['name']:'') ?>"></div>
<div><label for="course_id">Course</label><select id="course_id" name="course_id"><option value="">All courses</option><?php foreach($courses as $course): ?><option value="<?= e($course['id']) ?>" <?= (string)$course['id']===(string)($_GET['course_id']??'')?'selected':'' ?>><?= e($course['name']) ?></option><?php endforeach ?></select></div>
<div><label for="sort">Sort by</label><select id="sort" name="sort"><?php foreach(['id','name','email'] as $key): ?><option value="<?= e($key) ?>" <?= ($_GET['sort']??'id')===$key?'selected':'' ?>><?= e(ucfirst($key)) ?></option><?php endforeach ?></select></div>
<div><label for="direction">Direction</label><select id="direction" name="direction"><option value="asc">Ascending</option><option value="desc" <?= ($_GET['direction']??'')==='desc'?'selected':'' ?>>Descending</option></select></div><button type="submit">Apply filters</button></form>
<p><?= e($result['total']) ?> matching students · Page <?= e($result['page']) ?> of <?= e($result['pages']) ?></p>
<div class="table-wrap"><table><caption>Student records</caption><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Course</th><th>Actions</th></tr></thead><tbody>
<?php foreach($result['rows'] as $student): ?><tr><td><?= e($student['id']) ?></td><td><?= e($student['name']) ?></td><td><?= e($student['email']) ?></td><td><?= e($student['course']) ?></td><td class="actions"><a href="/students/<?= e($student['id']) ?>">View</a><?php if(in_array($role,['admin','teacher'],true)): ?><a href="/students/<?= e($student['id']) ?>/edit">Edit</a><?php endif ?><?php if($role==='admin'): ?><form method="post" action="/students/<?= e($student['id']) ?>/delete"><?= csrf() ?><button type="submit">Delete</button></form><?php endif ?></td></tr><?php endforeach ?>
<?php if(!$result['rows']): ?><tr><td colspan="5">No matching students.</td></tr><?php endif ?></tbody></table></div>
<nav aria-label="Pagination"><?php if($result['page']>1): ?><a href="/students?<?= e(http_build_query(array_merge($_GET,['page'=>$result['page']-1]))) ?>">Previous page</a><?php endif ?><?php if($result['page']<$result['pages']): ?><a href="/students?<?= e(http_build_query(array_merge($_GET,['page'=>$result['page']+1]))) ?>">Next page</a><?php endif ?></nav>
